    case 'transfer':
      return UnsignedTransferPackage.transfer(
        prepareTransfer: fromJsExternalPrepareTransferRequest(m['prepareTransfer']),
        amountSat: jsBigInt(m['amountSat']),
        feeSat: jsBigInt(m['feeSat']),
        target: fromJsTransferTarget(m['target']),
      );
    case 'token':
      return UnsignedTransferPackage.token(
        prepareTokenTransaction: fromJsExternalPrepareTokenTransactionRequest(m['prepareTokenTransaction']),
        tokenContext: jsBytes(m['tokenContext']),
        tokenIdentifier: jsString(m['tokenIdentifier']),
        amount: jsBigInt(m['amount']),
        fee: jsBigInt(m['fee']),
        isSwap: jsBool(m['isSwap']),
      );
    case 'tokenBatch':
      return UnsignedTransferPackage.tokenBatch(
        prepareTokenTransaction: fromJsExternalPrepareTokenTransactionRequest(m['prepareTokenTransaction']),
        tokenContext: jsBytes(m['tokenContext']),
        totals: jsList(m['totals'], (x) => fromJsBatchTotal(x)),
        isSwap: jsBool(m['isSwap']),
      );
  }
  throw ArgumentError.value(m['type'], 'UnsignedTransferPackage.type');
}

Map<String, Object?> toJsUnsignedTransferPackage(UnsignedTransferPackage v) => switch (v) {
  final UnsignedTransferPackage_Swap x => {
    'type': 'swap',
    'prepareTransfer': toJsExternalPrepareTransferRequest(x.prepareTransfer),
    'targetAmounts': jsFromU64List(x.targetAmounts),
    'amountSat': x.amountSat.toInt(),
    'feeSat': x.feeSat.toInt(),
  },
  final UnsignedTransferPackage_Transfer x => {
    'type': 'transfer',
    'prepareTransfer': toJsExternalPrepareTransferRequest(x.prepareTransfer),
    'amountSat': x.amountSat.toInt(),
    'feeSat': x.feeSat.toInt(),
    'target': toJsTransferTarget(x.target),
  },
  final UnsignedTransferPackage_Token x => {
    'type': 'token',
    'prepareTokenTransaction': toJsExternalPrepareTokenTransactionRequest(x.prepareTokenTransaction),
    'tokenContext': List<int>.of(x.tokenContext),
    'tokenIdentifier': x.tokenIdentifier,
    'amount': x.amount.toString(),
    'fee': x.fee.toString(),
    'isSwap': x.isSwap,
  },
  final UnsignedTransferPackage_TokenBatch x => {
    'type': 'tokenBatch',
    'prepareTokenTransaction': toJsExternalPrepareTokenTransactionRequest(x.prepareTokenTransaction),
    'tokenContext': List<int>.of(x.tokenContext),
    'totals': x.totals.map((x) => toJsBatchTotal(x)).toList(),
    'isSwap': x.isSwap,
  },
};

WebhookEventType fromJsWebhookEventType(Object? o) {
  if (o is String) o = {'type': o};
  final m = jsObj(o);
  switch (m['type']) {
    case 'lightningReceiveFinished':
      return WebhookEventType.lightningReceiveFinished();
    case 'lightningSendFinished':
      return WebhookEventType.lightningSendFinished();
    case 'coopExitFinished':
      return WebhookEventType.coopExitFinished();
    case 'staticDepositFinished':
      return WebhookEventType.staticDepositFinished();
    case 'unknown':
      return WebhookEventType.unknown(jsString(m['field0'] ?? m['value'] ?? m['message'] ?? ''));
  }
  throw ArgumentError.value(m['type'], 'WebhookEventType.type');
}

Map<String, Object?> toJsWebhookEventType(WebhookEventType v) => switch (v) {
  WebhookEventType_LightningReceiveFinished() => {'type': 'lightningReceiveFinished'},
  WebhookEventType_LightningSendFinished() => {'type': 'lightningSendFinished'},
  WebhookEventType_CoopExitFinished() => {'type': 'coopExitFinished'},
  WebhookEventType_StaticDepositFinished() => {'type': 'staticDepositFinished'},
  final WebhookEventType_Unknown x => {'type': 'unknown', 'field0': x.field0},
};
